local TimelineRuntime = nil

local function validMode(mode)
  return mode == "one-shot" or mode == "loop" or mode == "ambient"
end

local function normalizeMode(mode, loop)
  if validMode(mode) then return mode end
  return loop == true and "loop" or "one-shot"
end

local function timelineMode(instance)
  if instance and instance.mode ~= nil then return normalizeMode(instance.mode, instance.loop) end
  if timelineState.mode ~= nil then return normalizeMode(timelineState.mode, timelineState.loop) end
  return normalizeMode(timeline.mode, timeline.loop)
end

local function timelineShouldLoop(instance)
  return timelineMode(instance) == "loop"
end

local function clampTimelineValue(value, minValue, maxValue)
  value = tonumber(value) or 0
  if value < minValue then return minValue end
  if value > maxValue then return maxValue end
  return value
end

local function evaluatePlannedLane(lane, time, fallback)
  if not lane then return fallback end
  if lane.kind == "constant" then return lane.value end
  if lane.kind == "linear" then
    local points = lane.points
    local count = points and #points or 0
    if count == 0 then return fallback end
    if time <= points[1][1] then return points[1][2] end
    for index = 1, count - 1 do
      local a = points[index]
      local b = points[index + 1]
      local at = a[1]
      local bt = b[1]
      if time >= at and time <= bt then
        if a[3] == "hold" then return a[2] end
        local amount = clampTimelineValue((time - at) / math.max(0.0001, bt - at), 0, 1)
        return a[2] + (b[2] - a[2]) * amount
      end
    end
    return points[count][2]
  end
  return TimelineRuntime.evaluateKeyframes(lane.points, time, fallback)
end

local function clipAllowsEmission(clip, time, emitterLifetime, mode)
  local startTime = tonumber(clip and clip.start) or 0
  local endTime = tonumber(clip and clip["end"]) or 0
  if time < startTime then return false end
  local lifetime = tonumber(emitterLifetime) or -1
  if mode == "ambient" and lifetime < 0 then return true end
  if time > endTime then return false end
  if lifetime < 0 then return true end
  return time <= startTime + lifetime
end

local function trackAllowsEmission(track, time, emitterLifetime, mode)
  local clips = track and track.clips
  if not clips then return false end
  for index = 1, #clips do
    if clipAllowsEmission(clips[index], time, emitterLifetime, mode) then return true end
  end
  return false
end

local function timelineValues(emitter)
  local values = emitter.timelineValues
  if not values then
    values = {}
    emitter.timelineValues = values
  end
  return values
end

local function setTimelineValue(emitter, key, value, epsilon)
  local values = timelineValues(emitter)
  local previous = values[key]
  if previous == nil or math.abs(value - previous) > epsilon then
    values[key] = value
    return true
  end
  return false
end

local function invalidateTimelineValues(emitter)
  if not emitter then return end
  emitter.timelineValues = nil
  emitter.timelineSizes = nil
end

local function applyTimelinePlan(instance, time, allowEmission)
  if not instance then return end
  local mode = timelineMode(instance)
  local selectedIndex = instance.systemIndex
  local directionOffset = instance.directionOffset or 0
  for index = 1, #optimizedTimelinePlan.tracks do
    local track = optimizedTimelinePlan.tracks[index]
    local emitter = instance.systems[index]
    if emitter and emitter.enabled and emitter.system and (not selectedIndex or selectedIndex == index) then
      local ps = emitter.system
      local base = emitter.base or {}
      local lanes = track.lanes or {}
      local active = trackAllowsEmission(track, time, base.emitterLifetime, mode)
      local emissionRate = 0
      if active and allowEmission == true then
        emissionRate = math.max(0, evaluatePlannedLane(lanes.emissionRate, time, base.emissionRate or 0))
      end
      local particleChanged = false
      if setTimelineValue(emitter, "emissionRate", emissionRate, 0.5) then
        ps:setEmissionRate(emissionRate)
        particleChanged = true
      end
      if lanes.speedScale then
        local speedScale = math.max(0, evaluatePlannedLane(lanes.speedScale, time, 1))
        if setTimelineValue(emitter, "speedScale", speedScale, 0.001) then
          ps:setSpeed((base.speedMin or 0) * speedScale, (base.speedMax or 0) * speedScale)
          particleChanged = true
        end
      end
      if lanes.sizeScale then
        local sizeScale = math.max(0, evaluatePlannedLane(lanes.sizeScale, time, 1))
        local baseSizes = base.sizes
        if baseSizes and #baseSizes > 0 and setTimelineValue(emitter, "sizeScale", sizeScale, 0.001) then
          local scaled = emitter.timelineSizes
          if not scaled then scaled = {}; emitter.timelineSizes = scaled end
          for sizeIndex = 1, #baseSizes do scaled[sizeIndex] = math.max(0, baseSizes[sizeIndex] * sizeScale) end
          for sizeIndex = #baseSizes + 1, #scaled do scaled[sizeIndex] = nil end
          ps:setSizes(unpack(scaled))
          particleChanged = true
        end
      end
      if lanes.direction or setTimelineValue(emitter, "directionOffset", directionOffset, 0.0001) then
        local direction = evaluatePlannedLane(lanes.direction, time, base.direction or 0) + directionOffset
        if setTimelineValue(emitter, "direction", direction, 0.0001) then
          ps:setDirection(direction)
          particleChanged = true
        end
      end
      if lanes.spread then
        local spread = evaluatePlannedLane(lanes.spread, time, base.spread or 0)
        if setTimelineValue(emitter, "spread", spread, 0.0001) then
          ps:setSpread(spread)
          particleChanged = true
        end
      end
      if lanes.offsetX or lanes.offsetY then
        local offsetX = evaluatePlannedLane(lanes.offsetX, time, base.offsetX or 0)
        local offsetY = evaluatePlannedLane(lanes.offsetY, time, base.offsetY or 0)
        local offsetXChanged = setTimelineValue(emitter, "offsetX", offsetX, 0.01)
        local offsetYChanged = setTimelineValue(emitter, "offsetY", offsetY, 0.01)
        if offsetXChanged or offsetYChanged then
          ps:setOffset(offsetX, offsetY)
          particleChanged = true
        end
      end
      if lanes.opacity then
        local opacity = clampTimelineValue(evaluatePlannedLane(lanes.opacity, time, 1), 0, 1)
        if setTimelineValue(emitter, "opacity", opacity, 0.001) then emitter.opacity = opacity end
      end
      if particleChanged and emitter.variantSystems then syncAtlasVariants(emitter) end
    end
  end
end

local function applyTimeline(instance, time, allowEmission)
  applyTimelinePlan(instance, time, allowEmission)
end

local function shouldApplyTimeline(instance, dt)
  if timelineMode(instance) ~= "ambient" then
    instance.timelineDirty = false
    instance.timelineAccumulator = 0
    return true
  end
  if instance.timelineDirty then
    instance.timelineDirty = false
    instance.timelineAccumulator = 0
    return true
  end
  instance.timelineAccumulator = (instance.timelineAccumulator or 0) + dt
  if instance.timelineAccumulator >= TIMELINE_APPLY_INTERVAL then
    instance.timelineAccumulator = instance.timelineAccumulator % TIMELINE_APPLY_INTERVAL
    return true
  end
  return false
end

local function clipBurstCount(clip, emitter)
  local base = tonumber(clip.emit)
  if base == nil then base = tonumber(emitter.emitAtStart) end
  return math.max(0, math.floor(base or 0))
end

local function emitTimelineStarts(instance, previousTime, nextTime)
  if not instance then
    return
  end
  for index, track in ipairs(timeline.tracks or {}) do
    local emitter = instance.systems[index]
    if emitter and emitter.enabled and emitter.system and (not instance.systemIndex or instance.systemIndex == index) then
      for _, clip in ipairs(track.clips or {}) do
        local start = tonumber(clip.start) or 0
        if previousTime <= start and nextTime >= start then
          local count = clipBurstCount(clip, emitter)
          emitter.system:setEmitterLifetime((emitter.base and emitter.base.emitterLifetime) or -1)
          emitter.system:start()
          if emitter.variantSystems then syncAtlasVariants(emitter) end
          if count > 0 then emitAtlasSystems(emitter, count) end
        end
      end
    end
  end
end

local function emitTimelineStartsForAdvance(instance, previousTime, elapsed)
  if elapsed <= 0 then return previousTime end
  local cursor = previousTime
  local remaining = elapsed
  local guard = 0
  while remaining > 0 and guard < 128 do
    if cursor >= timeline.duration then cursor = 0 end
    local room = math.max(0, timeline.duration - cursor)
    if room <= 0 then cursor = 0; room = timeline.duration end
    local segment = math.min(remaining, room)
    local nextCursor = cursor + segment
    if segment > 0 then emitTimelineStarts(instance, cursor, nextCursor) end
    remaining = remaining - segment
    cursor = nextCursor
    if remaining > 0 and cursor >= timeline.duration then cursor = 0 end
    guard = guard + 1
  end
  return cursor >= timeline.duration and 0 or cursor
end

local function setMode(mode)
  if validMode(mode) then
    timelineState.mode = mode
    timelineState.loop = mode == "loop"
  else
    timelineState.mode = nil
    timelineState.loop = nil
  end
  for _, instance in ipairs(activeInstances) do
    instance.mode = timelineState.mode
    instance.loop = timelineState.loop
    instance.timelineDirty = true
  end
  return timelineMode(nil)
end

local function getMode()
  return timelineMode(nil)
end

local function setLoop(loop)
  if type(loop) == "boolean" then
    return setMode(loop and "loop" or "one-shot")
  end
  return setMode(nil)
end

local function resetInstance(instance, payload)
  payload = type(payload) == "table" and payload or {}
  local x = tonumber(payload.x) or particles.x
  local y = tonumber(payload.y) or particles.y
  instance.time = 0
  instance.playing = true
  instance.active = true
  if validMode(payload.mode) then
    instance.mode = payload.mode
  elseif type(payload.loop) == "boolean" then
    instance.mode = payload.loop and "loop" or "one-shot"
  else
    instance.mode = timelineState.mode
  end
  if validMode(instance.mode) then
    instance.loop = instance.mode == "loop"
  else
    instance.loop = timelineState.loop
  end
  instance.directionOffset = tonumber(payload.r) or 0
  instance.systemIndex = tonumber(payload.systemIndex)
  instance.timelineAccumulator = 0
  instance.timelineDirty = true
  for index, emitter in ipairs(instance.systems or {}) do
    local participates = not instance.systemIndex or instance.systemIndex == index
    if emitter.enabled and emitter.system then
      invalidateTimelineValues(emitter)
      for _, ps in ipairs(atlasSystems(emitter)) do ps:reset() end
      emitter.system:setEmitterLifetime((emitter.base and emitter.base.emitterLifetime) or -1)
      for _, ps in ipairs(atlasSystems(emitter)) do ps:setPosition(x + (emitter.x or 0), y + (emitter.y or 0)) end
      emitter.opacity = participates and 1 or 0
      if participates then
        for _, ps in ipairs(atlasSystems(emitter)) do ps:start() end
      else
        for _, ps in ipairs(atlasSystems(emitter)) do ps:setEmissionRate(0); ps:stop() end
      end
    end
  end
  applyTimeline(instance, 0, true)
  emitTimelineStarts(instance, 0, 0)
  return instance
end

local function retargetActiveAmbientInstance(payload)
  payload = type(payload) == "table" and payload or {}
  local requestedMode = validMode(payload.mode) and payload.mode or (type(payload.loop) == "boolean" and (payload.loop and "loop" or "one-shot") or timelineMode(nil))
  if requestedMode ~= "ambient" then return nil end
  for _, instance in ipairs(activeInstances) do
    if instance.active and timelineMode(instance) == "ambient" then
      local x = tonumber(payload.x) or particles.x
      local y = tonumber(payload.y) or particles.y
      instance.playing = true
      instance.mode = "ambient"
      instance.loop = false
      instance.directionOffset = tonumber(payload.r) or 0
      instance.systemIndex = tonumber(payload.systemIndex)
      instance.timelineAccumulator = 0
      instance.timelineDirty = true
      for index, emitter in ipairs(instance.systems or {}) do
        local participates = not instance.systemIndex or instance.systemIndex == index
        if emitter.enabled and emitter.system then
          invalidateTimelineValues(emitter)
          for _, ps in ipairs(atlasSystems(emitter)) do ps:setPosition(x + (emitter.x or 0), y + (emitter.y or 0)) end
          if participates then
            for _, ps in ipairs(atlasSystems(emitter)) do ps:start() end
          else
            for _, ps in ipairs(atlasSystems(emitter)) do ps:setEmissionRate(0); ps:stop() end
          end
        end
      end
      applyTimeline(instance, instance.time or 0, instance.playing)
      return instance
    end
  end
  return nil
end

local function recycleInstance(instance)
  if not instance then
    return
  end
  instance.active = false
  instance.playing = false
  instance.time = 0
  instance.mode = nil
  instance.loop = nil
  instance.directionOffset = 0
  instance.systemIndex = nil
  instance.timelineAccumulator = 0
  instance.timelineDirty = true
  for _, emitter in ipairs(instance.systems or {}) do
    if emitter.system then
      invalidateTimelineValues(emitter)
      for _, ps in ipairs(atlasSystems(emitter)) do ps:reset(); ps:setEmissionRate(0) end
      emitter.system:setEmitterLifetime((emitter.base and emitter.base.emitterLifetime) or -1)
    end
    emitter.opacity = 1
  end
  if #pooledInstances < MAX_POOLED_INSTANCES then
    pooledInstances[#pooledInstances + 1] = instance
  else
    releaseInstance(instance)
  end
end

local function checkoutInstance(payload)
  local ambient = retargetActiveAmbientInstance(payload)
  if ambient then
    publishSystems(ambient)
    return ambient
  end
  local instance = table.remove(pooledInstances)
  if not instance then
    instance = createInstance()
  end
  activeInstances[#activeInstances + 1] = instance
  resetInstance(instance, payload)
  publishSystems(instance)
  return instance
end

local function instanceHasParticles(instance)
  for _, emitter in ipairs(instance.systems or {}) do
    if emitter.enabled and emitter.system then
      for _, ps in ipairs(atlasSystems(emitter)) do
        local ok, count = pcall(ps.getCount, ps)
        if ok and (tonumber(count) or 0) > 0 then
          return true
        end
      end
    end
  end
  return false
end

local function update(dt)
  for i = #activeInstances, 1, -1 do
    local instance = activeInstances[i]
    if instance.playing then
      local previous = instance.time
      local nextTime = previous + dt
      if nextTime > timeline.duration then
        local mode = timelineMode(instance)
        if mode == "loop" then
          nextTime = emitTimelineStartsForAdvance(instance, previous, dt)
        elseif mode == "ambient" then
          emitTimelineStarts(instance, previous, timeline.duration)
          nextTime = timeline.duration
          instance.playing = true
        else
          emitTimelineStarts(instance, previous, timeline.duration)
          nextTime = timeline.duration
          instance.playing = false
        end
      else
        emitTimelineStarts(instance, previous, nextTime)
      end
      instance.time = nextTime
    end
    if shouldApplyTimeline(instance, dt) then
      applyTimeline(instance, instance.time, instance.playing)
    end
    for index, emitter in ipairs(instance.systems or {}) do
      if emitter.enabled and emitter.system and (not instance.systemIndex or instance.systemIndex == index) then
        for _, ps in ipairs(atlasSystems(emitter)) do ps:update(dt) end
      end
    end
    if not instance.playing and timelineMode(instance) ~= "ambient" and not instanceHasParticles(instance) then
      table.remove(activeInstances, i)
      recycleInstance(instance)
    end
  end
  local latest = activeInstances[#activeInstances]
  timelineState.time = latest and latest.time or 0
  timelineState.playing = latest and latest.playing or false
  if latest then
    timelineState.mode = latest.mode
    timelineState.loop = latest.loop
  end
  timelineState.directionOffset = latest and latest.directionOffset or 0
end

local function draw()
  local previousBlend, previousAlphaMode = LG.getBlendMode()
  local previousShader = LG.getShader()
  local r, g, b, a = LG.getColor()

  for _, instance in ipairs(activeInstances) do
    for index, emitter in ipairs(instance.systems or {}) do
      if emitter.enabled and emitter.system and (not instance.systemIndex or instance.systemIndex == index) then
        LG.setBlendMode(emitter.blendMode or "alpha")
        if emitter.shader and emitter.shader.send and love.timer then
          pcall(emitter.shader.send, emitter.shader, "u_time", love.timer.getTime())
        end
        LG.setShader(emitter.shader)
        LG.setColor(1, 1, 1, emitter.opacity or 1)
        for _, ps in ipairs(atlasSystems(emitter)) do LG.draw(ps, 0, 0) end
      end
    end
  end

  LG.setBlendMode(previousBlend, previousAlphaMode)
  LG.setShader(previousShader)
  LG.setColor(r, g, b, a)
end

---Play the authored particle timeline.
---@param payload ParticlePayload
local function play(payload)
  if type(payload) ~= "table" then
    payload = {}
  end
  return checkoutInstance(payload)
end

local function pause()
  timelineState.playing = false
  for _, instance in ipairs(activeInstances) do
    instance.playing = false
    applyTimeline(instance, instance.time, false)
  end
  return true
end

local function stop(resetParticles)
  timelineState.time = 0
  timelineState.playing = false
  timelineState.mode = nil
  timelineState.loop = nil
  timelineState.directionOffset = 0
  for i = #activeInstances, 1, -1 do
    local instance = activeInstances[i]
    instance.playing = false
    instance.mode = nil
    instance.loop = nil
    instance.directionOffset = 0
    applyTimeline(instance, instance.time or 0, false)
    if resetParticles ~= false then
      table.remove(activeInstances, i)
      recycleInstance(instance)
    end
  end
  if resetParticles ~= false then
    publishSystems(nil)
  end
  return true
end

local function emit(payload)
  return play(payload)
end

release = function()
  for i = #activeInstances, 1, -1 do
    releaseInstance(activeInstances[i])
    activeInstances[i] = nil
  end
  for i = #pooledInstances, 1, -1 do
    releaseInstance(pooledInstances[i])
    pooledInstances[i] = nil
  end
  clearSystemsAlias()
  return true
end

return {
  init = init,
  draw = draw,
  update = update,
  play = play,
  pause = pause,
  stop = stop,
  setMode = setMode,
  getMode = getMode,
  setLoop = setLoop,
  isLooping = timelineShouldLoop,
  emit = emit,
  release = release,
}
